// Product idea from the owner (Telegram photo, link or name; or JARVIS's tool) -> one clean request.
const b = ($input.first().json || {}).body || {};
const kind = ['photo', 'link', 'name'].includes(b.kind) ? b.kind : (b.url ? 'link' : b.image_b64 ? 'photo' : 'name');
let url = b.url || null, text = String(b.text || '').trim().slice(0, 300);
if (!url) { const m = text.match(/https?:\/\/\S+/); if (m) { url = m[0]; text = text.replace(m[0], '').trim(); } }
const okUrl = url && /^https?:\/\/[^\s/$.?#].[^\s]*$/i.test(url) && !/^https?:\/\/(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|\[?::1|0\.0\.0\.0|omniroute|jarvis-|n8n|postgres|caddy)/i.test(url);
const id = 'idea_' + Date.now().toString(36);
const problem = !text && !okUrl && !b.image_b64 ? 'Send me a product name, a link or a photo.' : null;
const message = problem || ('🔎 Checking ' + (kind === 'photo' ? 'your photo' : kind === 'link' ? 'this link' : '"' + text.slice(0, 60) + '"') +
  ': suppliers on CJ, competitor prices, Google searches in Canada, costs and risks. The report will arrive here in 1-3 minutes.');
return [{ json: { id, kind: okUrl ? 'link' : kind, url: okUrl ? url : null, text, image_b64: b.image_b64 || null, mime: b.mime || 'image/jpeg',
                  problem, reply: { ok: !problem, id, message } } }];

// What the linked page says about the product (title, image, price) - no scraping beyond this one page.
const req = $('Idea input').first().json;
const r = $input.first().json || {};
const html = String(r.data || r.body || (typeof r === 'string' ? r : '') || '').slice(0, 400000);
const meta = p => { const m = html.match(new RegExp('<meta[^>]+(?:property|name)=["\\\']' + p + '["\\\'][^>]*content=["\\\']([^"\\\']+)', 'i')) || html.match(new RegExp('<meta[^>]+content=["\\\']([^"\\\']+)["\\\'][^>]*(?:property|name)=["\\\']' + p, 'i')); return m ? m[1] : null; };
const title = meta('og:title') || meta('twitter:title') || ((html.match(/<title[^>]*>([^<]{3,200})<\/title>/i) || [])[1] || null);
const image = meta('og:image') || null;
const price = meta('product:price:amount') || meta('og:price:amount') || null;
const site = (req.url || '').replace(/^https?:\/\/(www\.)?/, '').split('/')[0];
const decode = s => s ? s.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim().slice(0, 200) : s;
return [{ json: { ...req, page: { title: decode(title), image: image && /^https:\/\//.test(image) ? image : null, price, site, fetched: !!html } } }];

// Ask the free AI what the product is (it can see the photo) and how to search for it.
const r = $input.first().json;
const page = r.page || {};
const sys = 'IDEA_IDENTIFY. You identify a consumer product for a Canadian dropshipping store. Reply with JSON only: ' +
  '{"name": "short generic product name in English (no brand)", "search_query": "2-4 English words to search suppliers", ' +
  '"category": "one word", "has_battery_or_charger": true|false, "is_beauty": true|false, "for_kids": true|false, "confidence": "high|medium|low"}';
const parts = [];
const hint = [r.text && 'Owner says: ' + r.text, page.title && 'Page title: ' + page.title, page.site && 'Site: ' + page.site, page.price && 'Page price: ' + page.price].filter(Boolean).join('\n');
parts.push({ type: 'text', text: hint || 'What product is in this photo?' });
if (r.image_b64) parts.push({ type: 'image_url', image_url: { url: 'data:' + (r.mime || 'image/jpeg') + ';base64,' + r.image_b64 } });
