  const amzPrice = m && m.amazon_median_cad ? m.amazon_median_cad : price;
  const perUnitFees = amzPrice * 0.15 + 5.50;
  fba = { units, stock_cad: R(stock), freight_cad: R(freight), total_cad: R(stock + freight), amazon_price_cad: R(amzPrice),
          fees_per_unit_cad: R(perUnitFees), profit_per_unit_cad: R(amzPrice - perUnitFees - (stock + freight) / units) };
}
const risks = [];
if (p.excluded) risks.push('Not allowed by your rules: ' + p.excluded);
(p.certification || []).concat(best ? best.certification || [] : []).filter((x, i, a) => a.indexOf(x) === i).forEach(c => risks.push('Certification: ' + c));
if (!best) risks.push('No matching product found on CJ');
if (best && best.competition === 'saturated') risks.push(best.listed_by_stores + ' stores already sell it on CJ (saturated)');
if (best && best.competition === 'unproven') risks.push('Few stores sell it yet (unproven)');
if (best && (best.days || 99) > 10) risks.push('Delivery over 10 days (' + (best.shipping ? best.shipping.days : '?') + ')');
if (m && m.trend === 'falling') risks.push('Google searches in Canada are falling');
if (!m || (m.median_price_cad === null && m.trend === null)) risks.push('No market data (SerpApi)');
if (ratio !== null && ratio < 2) risks.push('Market price is only ' + ratio + 'x our cost: thin room');
if (market_too_low) risks.push(`Not profitable at the market price: others sell at ~${m.median_price_cad} CAD; we would need ${price_needed} CAD to earn 10+ CAD`);
let verdict = 'MAYBE';
if (p.excluded || !best || market_too_low || (ratio !== null && ratio < 1.6) || (profit !== null && profit < 5)) verdict = 'NO';
else if (ratio !== null && ratio >= 2 && m.trend !== 'falling' && profit >= 10 && (best.days || 99) <= 10 && !risks.some(r => r.startsWith('Certification'))) verdict = 'GOOD';   // certification to check first = MAYBE
const sys = 'IDEA_LISTING. You write for Rangéo, a Canadian online store (Quebec): French first, then English. Original wording only (never copy the supplier text), ' +
  'no health or safety claims, no brand names, no fake reviews or fake scarcity. Describe exactly the item in supplier_title (that is what the customer receives), not a different product. Reply with JSON only: {"title_fr": "max 70 chars", "title_en": "max 70 chars", ' +
  '"description_html": "<p>French paragraph</p><ul><li>3 French benefit bullets</li></ul><p>English paragraph</p><ul><li>3 English bullets</li></ul>", ' +
  '"tags": ["5 lowercase tags"], "product_type": "one or two words", ' +
  '"videos": [{"hook": "first 2 seconds, max 8 words", "lines": ["3 short voice-over lines, max 12 words each"], "caption": "post caption, max 150 chars", "hashtags": ["5 hashtags"]}] ' +
  '(exactly 3 videos with DIFFERENT hooks: a problem hook, a surprise/demo hook, a gift hook for Christmas). English for the videos.}';
const facts = { product: p.name, supplier_title: best ? best.name : null, price_cad: price, warehouse: best ? best.warehouse : null, delivery_days: best ? best.shipping && best.shipping.days : null };
return [{ json: { id: p.id, name: p.name, q: p.q, kind: p.kind, url: p.url, page: p.page, verdict, risks, suppliers: sup, best, market: m, market_source: plan.source,
  serp_warning: plan.warning, ratio, price_cad: price, market_too_low, price_needed, fees_cad: R(fees), profit_cad: profit, profit_with_ads_cad: profit_ads,
  marketing: { videos_cad: 0, ad_test_cad, breakeven_sales }, fba, can_list: !!best && !p.excluded,   // the owner decides even on a weak verdict
  ai_body: { model: 'jarvis-free', max_tokens: 1400, temperature: 0.6, response_format: { type: 'json_object' },
             messages: [{ role: 'system', content: sys }, { role: 'user', content: JSON.stringify(facts) }] } } }];

// The full report for Telegram (HTML) + the approval text + the listing draft kept for after the approval.
const v = $('Verdict').first().json;
const ai = $input.first().json || {};
let L = {};
try { L = JSON.parse(String(ai.choices[0].message.content || '').replace(/^\s*```(?:json)?|```\s*$/g, '')); } catch (e) { L = {}; }
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const b = v.best, m = v.market || {};
const icon = { GOOD: '✅ GOOD', MAYBE: '🟡 MAYBE', NO: '⛔ NOT RECOMMENDED' }[v.verdict];
const lines = [`<b>Product check: ${esc(v.name)}</b>`, `Verdict: <b>${icon}</b>`];
if (m && (m.median_price_cad || m.trend)) {
  lines.push('', '<b>Market (Canada)</b>' + (v.market_source === 'cache' ? ' · saved check' : ''));
  if (m.trend) lines.push(`Google searches: ${m.trend} (${m.trend_pct > 0 ? '+' : ''}${m.trend_pct}% in 3 months)`);
  if (m.median_price_cad) lines.push(`Others sell at ~${m.median_price_cad} CAD (${m.offers} offers)` + (v.ratio ? `, ${v.ratio}× our cost` : ''));
  lines.push('Amazon.ca: ' + (m.amazon_median_cad ? `~${m.amazon_median_cad} CAD (${m.amazon_offers} offer${m.amazon_offers > 1 ? 's' : ''} in Google Shopping)` : 'not seen in Google Shopping'));
  if (m.others && m.others.length) lines.push('Other stores: ' + m.others.map(o => `${esc(o.source)} ${o.price} CAD`).join(', '));
} else lines.push('', 'Market: no data' + (v.serp_warning ? ' (' + esc(v.serp_warning) + ')' : ''));
lines.push('TikTok Shop: no official data available (JARVIS does not scrape TikTok).');
if (v.suppliers.length) {
  lines.push('', '<b>Best suppliers (CJ)</b>');
  v.suppliers.forEach((s, i) => lines.push(`${i + 1}. ${esc(s.name.slice(0, 70))} · ${s.warehouse === 'CN' ? '📦 China' : '🚚 ' + s.warehouse} · ${s.cost_usd.toFixed(2)} USD + ship ` +
    (s.shipping ? `${s.shipping.usd.toFixed(2)} USD (${esc(s.shipping.days)} days) = ${s.landed_cad} CAD` : '? (no shipping quote to Canada from this warehouse)') + ` · ${s.listed_by_stores} stores · SKU ${esc(s.sku)}`));
}
if (b) {
  lines.push('', '<b>Money (best supplier, estimates)</b>',
    `Supplier ${b.cost_usd.toFixed(2)} USD + shipping ${b.shipping ? b.shipping.usd.toFixed(2) : '?'} USD = landed ${b.landed_cad} CAD`,
    v.market_too_low ? `Price: others sell at ~${m.median_price_cad} CAD. At that price you'd earn only <b>${v.profit_cad} CAD</b>; to earn 10+ CAD you'd need ${v.price_needed} CAD, above the market. ⛔ Not profitable.`
      : `Suggested price: <b>${v.price_cad} CAD</b> (shipping included)`,
    `Fees: payment ${v.fees_cad} CAD + 5% returns allowance`,
    `Profit per sale: <b>${v.profit_cad} CAD</b> (${v.profit_with_ads_cad} CAD if 20% goes to ads)`,
    `Marketing: 3 videos by JARVIS = 0 CAD · small ad test ${v.marketing.ad_test_cad} CAD (5 days × 10 CAD, only if you approve)` + (v.marketing.breakeven_sales ? ` · pays back after ${v.marketing.breakeven_sales} sales` : ''));
  if (v.fba) lines.push(`Amazon FBA (rough): ${v.fba.units} units = ${v.fba.stock_cad} CAD stock + ~${v.fba.freight_cad} CAD freight = <b>${v.fba.total_cad} CAD up front</b>; at ${v.fba.amazon_price_cad} CAD Amazon fees ~${v.fba.fees_per_unit_cad} CAD/unit, profit ~${v.fba.profit_per_unit_cad} CAD/unit. Waits for your seller account.`);
}
lines.push('', '<b>Risks</b>', v.risks.length ? v.risks.map(r => '• ' + esc(r)).join('\n') : '• none found');
if (L.title_fr || L.title_en) lines.push('', `<b>Listing draft</b>: ${esc(L.title_fr || '')}${L.title_en ? ' / ' + esc(L.title_en) : ''}`);
lines.push('', v.can_list ? 'Tap Approve below to list it on Rangéo (Shopify) at ' + v.price_cad + ' CAD. The video team then makes 3 short videos.' : 'Not offered for listing (see risks).');
const report = lines.join('\n').slice(0, 4000);
const mdEsc = t => String(t ?? '').replace(/([_*`\[])/g, '\\$1');
const approval_text = `*List on Rangéo?* ${mdEsc(L.title_fr || v.name)}\nPrice ${mdEsc(v.price_cad)} CAD, profit ~${mdEsc(v.profit_cad)} CAD per sale, verdict ${v.verdict}.\nApprove = I create the product on Shopify (active, with photos) and send you the live link. Decline = nothing happens.`;
const day = new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto', dateStyle: 'medium', timeStyle: 'short' });
const summary = `Product idea check (${day}): ${v.name} - verdict ${v.verdict}` + (b ? `, best supplier CJ SKU ${b.sku} (${b.warehouse} warehouse), landed ${b.landed_cad} CAD, suggested price ${v.price_cad} CAD, profit ~${v.profit_cad} CAD` : ', no supplier found') +
  (m && m.median_price_cad ? `, market ~${m.median_price_cad} CAD` : '') + (m && m.trend ? `, searches ${m.trend}` : '') + '. Report sent on Telegram' + (v.can_list ? ' with Approve/Decline.' : '.');
const photo = (b && b.image) || (v.page && v.page.image) || '';
return [{ json: { ...v, listing: { title_fr: String(L.title_fr || v.name).slice(0, 120), title_en: String(L.title_en || '').slice(0, 120),
  description_html: String(L.description_html || '<p>' + esc(v.name) + '</p>').slice(0, 6000), tags: Array.isArray(L.tags) ? L.tags.slice(0, 8).map(String) : [],
  product_type: String(L.product_type || '').slice(0, 60), videos: Array.isArray(L.videos) ? L.videos.slice(0, 3) : [] },
  report, approval_text, photo, has_photo: !!photo, caption: `<b>${esc(v.name)}</b> · ${icon}`, kind: 'idea', summary: summary.slice(0, 1500) } }];

// The owner's answer to "List on Rangéo?" (Approve / Decline / no answer in 72 h).
const r = $input.first().json || {};
const approved = (r.data ? r.data.approved : r.approved) === true;
const rep = $('Report').first().json;
const day = new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto', dateStyle: 'medium', timeStyle: 'short' });
return [{ json: { approved, kind: 'approval', summary: `Listing approval (${day}): ${rep.name} at ${rep.price_cad} CAD - ${approved ? 'APPROVED by the owner: JARVIS lists it on Shopify and makes 3 videos' : 'DECLINED by the owner (or no answer in 72 h): nothing listed'}.`,
  reply_text: approved ? `✅ Approved. Creating "${rep.listing.title_fr}" on Rangéo now...` : `❌ Declined: ${rep.name}. Nothing was listed.` } }];

// Shopify product (GraphQL productSet): original title and description, CJ photos, price, collection, CJ SKU.
// Active on the Online Store right after the owner's approval.
const rep = $('Report').first().json;
const g = ($input.first().json || {}).data || {};
let cj = {};
try { cj = ($('CJ product photos').first().json || {}).data || {}; } catch (e) { cj = {}; }
let imgs = cj.productImageSet || cj.productImage || [];
if (typeof imgs === 'string') { try { imgs = imgs.trim().startsWith('[') ? JSON.parse(imgs) : [imgs]; } catch (e) { imgs = [imgs]; } }
imgs = [...new Set([rep.best && rep.best.image, ...(Array.isArray(imgs) ? imgs : [])].filter(u => typeof u === 'string' && /^https?:\/\//.test(u)).map(u => u.replace(/^http:/, 'https:')))].slice(0, 6);
const words = t => new Set(String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 3));
const want = words([rep.listing.product_type, rep.listing.tags.join(' '), rep.name, rep.listing.title_en].join(' '));
const cols = ((g.collections || {}).nodes || []).map(c => ({ ...c, score: [...words(c.title)].filter(w => want.has(w)).length }));
cols.sort((a, b) => b.score - a.score);
const collection = cols[0] && cols[0].score > 0 ? cols[0] : null;
const pub = ((g.publications || {}).nodes || []).find(p => /online store|boutique en ligne/i.test(p.name)) || null;
const sku = (rep.best && (rep.best.variant_sku || rep.best.sku)) || '';
const input = {
  title: rep.listing.title_fr, descriptionHtml: rep.listing.description_html, vendor: 'Rangéo', productType: rep.listing.product_type || 'Accessoires',
  tags: [...rep.listing.tags, 'jarvis', 'cj-' + (rep.best ? rep.best.warehouse.toLowerCase() : 'cn')].slice(0, 10), status: 'ACTIVE',
  productOptions: [{ name: 'Title', position: 1, values: [{ name: 'Default Title' }] }],
  variants: [{ optionValues: [{ optionName: 'Title', name: 'Default Title' }], price: String(rep.price_cad), inventoryPolicy: 'CONTINUE',
               inventoryItem: { sku, tracked: false, requiresShipping: true } }],
  files: imgs.map((u, i) => ({ originalSource: u, contentType: 'IMAGE', alt: rep.listing.title_fr + (i ? ' ' + (i + 1) : '') })),
};
if (collection) input.collections = [collection.id];
const query = 'mutation productSet($input: ProductSetInput!, $synchronous: Boolean!) { productSet(synchronous: $synchronous, input: $input) { product { id handle onlineStoreUrl } userErrors { field message } } }';
return [{ json: { gql: { query, variables: { input, synchronous: true } }, publication_id: pub ? pub.id : null, collection: collection ? collection.title : null,
                  images: imgs.length, sku, shop_error: g.errors || ($input.first().json || {}).errors || null } }];

// Live link (or what went wrong) for the owner, and a memory row.
const inp = $('Product for Shopify').first().json;
const rep = $('Report').first().json;
const created = $('Shopify: create product').first().json || {};
const res = (created.data && created.data.productSet) || {};
const errs = (res.userErrors || []).map(e => e.message).concat(created.errors ? [].concat(created.errors).map(e => e.message || String(e)) : []).concat(created.error ? [String(created.error.message || created.error)] : []);
let pubErr = null;
try { const p = $('Publish to Online Store').first().json || {}; const ue = (p.data && p.data.publishablePublish && p.data.publishablePublish.userErrors) || []; if (ue.length || p.errors || p.error) pubErr = (ue[0] && ue[0].message) || JSON.stringify(p.errors || p.error).slice(0, 200); } catch (e) { pubErr = 'not run'; }
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ok = !!(res.product && res.product.handle) && !errs.length;
const link = ok ? (res.product.onlineStoreUrl || 'https://rangeo-ca.myshopify.com/products/' + res.product.handle) : null;
const day = new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto', dateStyle: 'medium', timeStyle: 'short' });
const text = ok
  ? `🟢 <b>Live on Rangéo</b>: ${esc(rep.listing.title_fr)}\n${esc(link)}\nPrice ${rep.price_cad} CAD · ${inp.images} photo(s) · collection: ${esc(inp.collection || 'none matched')}` +
    (pubErr ? `\n⚠️ Online Store publishing: ${esc(pubErr)}. In Shopify > Products, open it and tick Online Store.` : '') +
    `\n\n<b>One step for you (1 min):</b> in the CJ app (Shopify > Apps > CJdropshipping > Products > Connection), connect this product to CJ SKU ${esc(inp.sku)} so orders go to CJ automatically.` +
    `\n<b>Amazon:</b> when your seller account and SP-API are connected, I'll prepare the Amazon listing and the FBA stock order (about ${rep.fba ? rep.fba.total_cad : '?'} CAD) and ask your approval separately before buying any stock.` +
    '\n🎬 The video team is making 3 short videos now.'
  : `⚠️ <b>Shopify listing failed</b> for ${esc(rep.listing.title_fr)}: ${esc(errs.join('; ') || 'no answer from Shopify')}.\nCheck the Shopify credential (custom app with write_products, read_publications and write_publications). Nothing was published.`;
return [{ json: { ok, link, text, kind: 'listing', summary: ok ? `Listed on Shopify (${day}): ${rep.listing.title_fr} at ${rep.price_cad} CAD, CJ SKU ${inp.sku}, ${link}. Owner must connect it in the CJ app.` : `Shopify listing FAILED (${day}) for ${rep.name}: ${errs.join('; ').slice(0, 300)}` } }];

// Video team: 3 short vertical videos (different hooks) from the product photos + JARVIS's voice.
// The server's voice service renders each one (POST /video); captions and hashtags go with each video.
const rep = $('Report').first().json;
const imgs = ($('Product for Shopify').first().json.gql.variables.input.files || []).map(f => f.originalSource).slice(0, 5);
let vids = rep.listing.videos || [];
const name = rep.name;
const fallback = [
  { hook: `Still struggling with this?`, lines: [`Meet the ${name}.`, 'Simple, useful, and ready for every day.', 'Link in bio.'], caption: name, hashtags: ['#rangeo', '#canada', '#homefinds', '#musthave', '#giftideas'] },
  { hook: `You need to see this`, lines: [`The ${name} does the job in seconds.`, 'No mess, no fuss.', 'Shop it at Rangéo.'], caption: name, hashtags: ['#rangeo', '#canada', '#tiktokmademebuyit', '#gadget', '#shopsmall'] },
  { hook: `Gift idea under ${Math.ceil(rep.price_cad)} dollars`, lines: [`The ${name}.`, 'Fast delivery in Canada.', 'Order before Christmas.'], caption: name, hashtags: ['#rangeo', '#christmasgift', '#giftideas', '#canada', '#blackfriday'] },
];
while (vids.length < 3) vids.push(fallback[vids.length]);
vids = vids.slice(0, 3).map((v, i) => ({ hook: String(v.hook || fallback[i].hook).slice(0, 60),
  lines: (Array.isArray(v.lines) && v.lines.length ? v.lines : fallback[i].lines).slice(0, 3).map(l => String(l).slice(0, 90)),
  caption: String(v.caption || fallback[i].caption).slice(0, 150),
  hashtags: (Array.isArray(v.hashtags) && v.hashtags.length ? v.hashtags : fallback[i].hashtags).slice(0, 6).map(h => '#' + String(h).replace(/^#+/, '').replace(/\s+/g, '')) }));
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const scripts = '<b>🎬 Video team: 3 scripts for ' + esc(rep.listing.title_fr) + '</b>\n' + vids.map((v, i) => `\n<b>${i + 1}. Hook:</b> ${esc(v.hook)}\nVoice: ${esc(v.lines.join(' '))}\nCaption: ${esc(v.caption)} ${esc(v.hashtags.join(' '))}`).join('\n') +
  '\n\nThe videos follow. Post them yourself on TikTok, Reels and Shorts (auto-posting needs each platform\'s API approval).';
return vids.map((v, i) => ({ json: { n: i + 1, scripts, caption: `${v.caption}\n${v.hashtags.join(' ')}`.slice(0, 1000),
  video_body: { images: imgs.length ? imgs : [rep.photo].filter(Boolean), hook: v.hook, lines: v.lines, voice: 'am_adam', price: `${rep.price_cad} CAD`, brand: 'Rangéo' } } }));
